        depth: 2,
        text: "Use flexRenderComponent(...) for Angular component cells. Put ngGridCellWidget from @angular/aria/grid on the real focusable element inside the custom component. import { Component, input, output } from '@angular/core'; import { GridCellWidget } from '@angular/aria/grid'; import { flexRenderComponent } from 'ng-advanced-table'; @Component({ selector: 'app-trade-button', imports: [GridCellWidget], template: ` <button type=\"button\" ngGridCellWidget [attr.aria-label]=\"accessibleName()\" (click)=\"pressed.emit()\">Trade</button> ` }) export class TradeButton { readonly accessibleName = input.required<string>(); readonly pressed = output<void>(); } { id: 'trade', header: 'Trade', enableSorting: false, enableGlobalFilter: false, meta: { label: 'Trade', hiddenHeaderLabel: 'Trade actions' }, cell: (context) => flexRenderComponent(TradeButton, { inputs: { accessibleName: `Trade ${context.row.original.symbol}`, }, outputs: { pressed: () => this.openTradeTicket(context.row.original.id), }, }), } (rowActivate) is for row-level primary actions. It ignores events from interactive descendants such as buttons, links, inputs, menu items, and contenteditable regions."
